TODAY = dt.date(2026, 11, 9)
MONTHS = ["января", "февраля", "марта", "апреля", "мая", "июня", "июля", "августа", "сентября", "октября", "ноября", "декабря"]


def d(day: dt.date) -> str:
    return f"{day.day} {MONTHS[day.month - 1]} {day.year} г."


def rub(x: float) -> str:
    whole = int(round(x * 100)) // 100
    kop = int(round(x * 100)) % 100
    s = f"{whole:,}".replace(",", " ")
    return f"{s},{kop:02d} руб." if kop else f"{s} руб."


def mln(x: int) -> str:
    return f"{x / 1_000_000:g}".replace(".", ",") + " млн руб."


