# Переход между договорами внутри диалога (follow-up без названия договора — модель должна держать контекст)
CROSS = [("p17_pay", "pt05_pay", "А по договору с «Альфа-Трейдинг»?"), ("pt05_warranty", "p17_warranty", "А по договору с «Альфа-Трейд»?"),
         ("p17_penalty", "pt05_penalty", "А у «Альфа-Трейдинг» какая?"), ("pt05_delivery", "p17_delivery", "А у «Альфа-Трейд»?")]


def gen_dialogs():
    for k1, k2 in DIALOG_PAIRS:
        q1, _, a1, _, _, _ = FACTS[k1]
        _, follow, a2, s2, _, _ = FACTS[k2]
        add("dialog", dlg(q1, a1, follow), a2, s2)
    for k1, k2, follow in CROSS:
        add("dialog", dlg(FACTS[k1][0], FACTS[k1][2], follow), FACTS[k2][2], FACTS[k2][3])


def gen_false_premise():
    for key in ["p17_pay", "p17_delivery", "p17_penalty", "p17_claim", "p17_quality", "p17_term", "p17_price", "pt05_pay",
                "pt05_delivery", "pt05_warranty", "pt05_penalty", "pt05_disputes", "pt05_owner", "a_increase", "a_deposit",
                "a_penalty", "a_sublease", "a_access", "a_area", "sz_issue", "sz_scan", "r25_terms", "r25_gd", "r25_original",
                "tk70", "tk152", "mrot", "vat"]:
        _, _, ans, s, wrong_q, _ = FACTS[key]
        add("false_premise", wrong_q, f"Это не так. {ans}", s)


