# ═════════════════════ расчёты (считаются кодом) ═════════════════════
def ndfl(x: int) -> float:
    if x <= 2_400_000:
        return 0.13 * x
    if x <= 5_000_000:
        return 312_000 + 0.15 * (x - 2_400_000)
    if x <= 20_000_000:
        return 702_000 + 0.18 * (x - 5_000_000)
    if x <= 50_000_000:
        return 3_402_000 + 0.20 * (x - 20_000_000)
    return 9_402_000 + 0.22 * (x - 50_000_000)


def weekday_ok(day: dt.date) -> bool:
    return day.weekday() < 5


