def route(date: dt.date | None, amount: int, kind: str) -> tuple[str, str, bool]:
    """Возвращает (ответ, источники, multi_doc)."""
    name, flags = KINDS[kind]
    when = date or TODAY
    parts, srcs = [], []
    if when < R25_START:
        intro = f"На {d(when)} действовал Регламент в ред. от 10.01.2023 (новая редакция — с 01.03.2025)."
        parts.append("согласование с юридическим отделом и главным бухгалтером (п. 2.1)")
        srcs.append((R23, "п. 2.1"))
        if amount > 1_000_000:
            parts.append("с финансовым директором — сумма свыше 1 млн руб. (п. 2.3)")
            srcs.append((R23, "п. 2.3"))
        if amount > 10_000_000:
            parts.append("одобрение генерального директора до подписания — свыше 10 млн руб. (п. 2.4)")
            srcs.append((R23, "п. 2.4"))
        if "foreign" in flags:
            parts.append("дополнительное согласование с юротделом в части применимого права (п. 4.1)")
            srcs.append((R23, "п. 4.1"))
        parts.append("лист согласования — на бумаге (п. 3.1)")
        srcs.append((R23, "п. 3.1"))
        extra = ""
        if flags - {"foreign"}:
            extra = " Специальных требований для такого вида договоров эта редакция не содержала (они появились в ред. от 01.03.2025)."
        multi = False
    else:
        intro = "Действует Регламент в ред. от 01.03.2025." if date is None else f"На {d(when)} действовал Регламент в ред. от 01.03.2025."
        parts.append("согласование в СЭД с юридическим отделом (3 р. д.) и главным бухгалтером (2 р. д.) (пп. 2.1–2.2, 3.1)")
        srcs += [(R25, "п. 2.1"), (R25, "п. 2.2")]
        fin = []
        if amount > 3_000_000:
            fin.append("сумма свыше 3 млн руб. (п. 2.3)")
            srcs.append((R25, "п. 2.3"))
        if "guar" in flags:
            fin.append("поручительство — независимо от суммы (п. 2.5)")
            srcs.append((R25, "п. 2.5"))
        if "aff" in flags:
            fin.append("аффилированное лицо — независимо от суммы (п. 5.3)")
            srcs.append((R25, "п. 5.3"))
        if fin:
            parts.append("с финансовым директором: " + "; ".join(fin))
        if amount > 15_000_000:
            parts.append("одобрение генерального директора до подписания — свыше 15 млн руб. (п. 2.4)")
            srcs.append((R25, "п. 2.4"))
        if "lease" in flags:
            parts.append("с административно-хозяйственным отделом — аренда недвижимости (п. 5.1)")
            srcs.append((R25, "п. 5.1"))
        if "pd" in flags:
            parts.append("с ответственным за организацию обработки персональных данных (п. 5.2)")
            srcs.append((R25, "п. 5.2"))
        multi = False
        if "foreign" in flags:
            parts.append("проверка юротделом (в т. ч. применимое право и порядок разрешения споров) и валютный контроль финансовым отделом (п. 5.4)")
            srcs.append((R25, "п. 5.4"))
            if when >= K12_START:
                parts.append("санкционная проверка службой комплаенс по Чек-листу до подписания, 3 рабочих дня, заключение — в СЭД; без него договор не подписывается (письмо № К-12)")
                srcs.append((K12, "абз. 3–6"))
                multi = True
        extra = ""
        if "foreign" in flags and when < K12_START:
            extra = " Санкционная проверка по письму № К-12 тогда ещё не требовалась (применяется с 21.04.2025)."
    text = f"{intro} Нужно: " + "; ".join(parts) + "." + extra
    return text, src(*srcs), multi


def gen_routes():
    past = [
        (dt.date(2024, 6, 10), 800_000, "supply"), (dt.date(2024, 6, 10), 5_000_000, "lease"), (dt.date(2024, 11, 20), 12_000_000, "supply"),
        (dt.date(2025, 2, 25), 2_000_000, "pd"), (dt.date(2025, 2, 25), 500_000, "guar"), (dt.date(2025, 3, 3), 500_000, "guar"),
        (dt.date(2025, 3, 3), 2_000_000, "aff"), (dt.date(2024, 9, 2), 1_000_000, "aff"), (dt.date(2025, 4, 10), 4_000_000, "foreign"),
        (dt.date(2025, 4, 25), 4_000_000, "foreign"), (dt.date(2024, 12, 16), 7_000_000, "foreign"), (dt.date(2025, 7, 1), 18_000_000, "lease"),
        (dt.date(2025, 1, 15), 11_000_000, "lease"), (dt.date(2025, 10, 6), 2_900_000, "supply"), (dt.date(2025, 2, 28), 16_000_000, "supply"),
        (dt.date(2025, 3, 1), 16_000_000, "supply"), (dt.date(2025, 5, 19), 1_500_000, "pd"), (dt.date(2024, 4, 8), 3_500_000, "foreign_lease"),
        (dt.date(2025, 9, 1), 3_500_000, "foreign_lease"),
    ]
    for date, amount, kind in past:
        text, s, _ = route(date, amount, kind)
        add("edition_date", f"{KINDS[kind][0].capitalize()} на {mln(amount)} подписали {d(date)} Какой был порядок согласования?", text, s)
    now = [(900_000, "supply"), (3_200_000, "supply"), (25_000_000, "supply"), (2_000_000, "lease"), (16_000_000, "lease"),
           (700_000, "pd"), (300_000, "aff"), (100_000, "guar"), (2_500_000, "foreign"), (20_000_000, "foreign"), (8_000_000, "foreign_lease"),
           (4_000_000, "pd")]
    for amount, kind in now:
        text, s, multi = route(None, amount, kind)
        add("multi_doc" if multi else "steps", f"Сейчас заключаем {KINDS[kind][0]} на {mln(amount)}. Какие шаги согласования?", text, s)


