STEPS = [
    ("Как взять оригинал договора из архива?", "Подать заявку в СЭД; оригинал выдаётся сотрудникам других подразделений на срок не более 3 рабочих дней; хранится в архиве юротдела, каб. 412 (служебная записка № ЮО-7).", src((SZ, "абз. 1, 3"))),
    ("Как отказаться от договора с «Альфа-Трейд»?", "Направить «Альфа-Трейд» письменное уведомление об отказе не менее чем за 60 календарных дней (п. 9.2 договора № П-17/2024); до этого исполнять обязательства, в т. ч. оплату поставленных партий (п. 4.2). Договор в любом случае действует до 31.12.2026 (п. 9.1).", src((P17, "п. 9.2"), (P17, "п. 9.1"))),
    ("Как заказать технику у «Альфа-Трейдинг»?", "1) Отправить заявку по e-mail с наименованием, количеством и желаемой датой (п. 1.2). 2) Поставка — в течение 14 рабочих дней (п. 3.1) по адресу в Москве из заявки (п. 3.2). 3) Подписать товарную накладную — переходит право собственности (п. 3.3). 4) Оплатить в течение 45 календарных дней (п. 4.1 договора № ПТ-05/2023).", src((PT05, "п. 1.2"), (PT05, "п. 3.1"), (PT05, "п. 3.3"), (PT05, "п. 4.1"))),
    ("Как получить партию мебели от «Альфа-Трейд» по шагам?", "1) Подписать Спецификацию на партию (пп. 1.2, 3.1). 2) Поставка в течение 10 рабочих дней по адресу: для спецификаций после 01.10.2024 — Химки, Заводская, 15, склад № 3 (доп. соглашение № 1). 3) Приёмка по количеству при передаче, по качеству — 5 рабочих дней (п. 6.1). 4) Подписать УПД — это дата поставки (п. 3.3). 5) Оплатить в течение 30 календарных дней с УПД (п. 4.2).", src((P17, "п. 3.1"), (DS1, "п. 3.2 в новой ред."), (P17, "п. 6.1"), (P17, "п. 3.3"), (P17, "п. 4.2"))),
    ("У нас форс-мажор, не можем оплатить «Альфа-Трейд» вовремя. Что делать?", "Уведомить «Альфа-Трейд» в течение 5 рабочих дней с момента наступления обстоятельств непреодолимой силы — это условие освобождения от ответственности (п. 7.4 договора № П-17/2024). Иначе — неустойка 0,1% в день, не более 10% (п. 7.2).", src((P17, "п. 7.4"), (P17, "п. 7.2"))),
    ("Как правильно установить испытательный срок новому сотруднику?", "1) Включить условие об испытании в трудовой договор по соглашению сторон (ТК РФ, ст. 70). 2) Проверить, что работник не из категорий, кому испытание не устанавливается (беременные, до 18 лет, по конкурсу и др.). 3) Срок — до 3 месяцев (руководители, главбухи — до 6); при договоре на 2–6 месяцев — до 2 недель; до 2 месяцев — испытания нет.", src((TK70, "ст. 70"))),
    ("Как оформить сезонного работника на лето?", "Заключить срочный трудовой договор — основание: сезонные работы, которые по природным условиям выполняются только в определённый сезон (ТК РФ, ст. 59). Если договор на 2–6 месяцев, испытание — не более 2 недель; до 2 месяцев — испытание не устанавливается (ст. 70).", src((TK59, "ч. 1"), (TK70, "ч. 4, 6"))),
    ("Как правильно получить согласие клиента на обработку персональных данных?", "1) Оформить согласие отдельно от иных документов; оно должно быть конкретным, предметным, информированным, сознательным и однозначным (ч. 1 ст. 9 152-ФЗ). 2) Где нужна письменная форма — включить реквизиты по ч. 4 (ФИО, документ, оператор, цель, перечень данных и действий, срок и способ отзыва, подпись). 3) Хранить доказательства — бремя доказывания на операторе (ч. 3).", src((FZ152, "ч. 1, 3, 4"))),
    ("Клиент отозвал согласие на обработку данных. Что делать?", "Субъект вправе отозвать согласие (ч. 2 ст. 9 152-ФЗ). Обработку без согласия можно продолжить только при основаниях из пп. 2–11 ч. 1 ст. 6, ч. 2 ст. 10 и ч. 2 ст. 11 закона; этих статей в базе нет, поэтому проверку оснований нужно провести отдельно.", src((FZ152, "ч. 2"))),
    ("Как оформить освобождение от НДС по шагам?", "1) Проверить, что выручка без НДС за 3 последовательных месяца не больше 2 млн руб. (п. 1 ст. 145 НК РФ) и нет подакцизных товаров (п. 2). 2) До 20-го числа месяца начала освобождения подать уведомление и документы: выписки из баланса, книги продаж (пп. 3, 6). 3) 12 месяцев отказаться нельзя (п. 4). 4) По истечении — подтверждающие документы и уведомление о продлении или отказе.", src((NK145, "пп. 1–4, 6"))),
    ("Как провести санкционную проверку иностранного контрагента?", "1) Инициатор направляет запрос в службу комплаенс до подписания договора. 2) Проверка по Чек-листу: контрагент и бенефициары по санкционным спискам, юрисдикция, банк, товар на ограничения ввоза/вывоза. 3) Срок — 3 рабочих дня. 4) Заключение прикладывается к договору в СЭД; без него договор не подписывается (письмо № К-12).", src((K12, "абз. 3–6, прил. 1"))),
    ("Хотим сдать часть склада в субаренду. Как это сделать?", "Получить письменное согласие ООО «Северный Склад» (п. 4.2 договора № А-08/2024); изменения и дополнения к договору оформляются письменными доп. соглашениями (п. 6.1).", src((A, "п. 4.2"), (A, "п. 6.1"))),
    ("«Северный Склад» прислал уведомление о повышении аренды на 10%. Что делать?", "Проверить по п. 3.4 договора № А-08/2024: повышение возможно не чаще раза в год и не более чем на 7%, с письменным уведомлением. Повышение на 10% превышает лимит; правомерно не более 481 500 руб. в месяц (450 000 × 1,07).", src((A, "п. 3.4"), (A, "п. 3.1"))),
    ("Просрочили аренду. Что будет и что делать?", "Оплатить задолженность: начисляются пени 0,1% от суммы задолженности за каждый день просрочки (п. 5.1 договора № А-08/2024); плата вносится не позднее 5-го числа месяца (п. 3.2).", src((A, "п. 5.1"), (A, "п. 3.2"))),
    ("Подписали договор с иностранной компанией. Что делать с документами дальше?", "Заключение службы комплаенс должно быть приложено к договору в СЭД (письмо № К-12); подписанный оригинал — передать в юротдел в течение 3 рабочих дней (п. 3.2 Регламента в ред. от 01.03.2025); скан размещается в СЭД не позднее 1 рабочего дня после поступления оригинала в архив (служебная записка № ЮО-7).", src((K12, "абз. 4"), (R25, "п. 3.2"), (SZ, "абз. 4"))),
    ("«Альфа-Трейдинг» просрочил поставку. Как действовать?", "По договору № ПТ-05/2023 обязательной претензии нет: споры решаются переговорами, при недостижении согласия — в Арбитражном суде г. Москвы (п. 7.1). Можно требовать неустойку 0,05% от стоимости непоставленного товара за каждый день (п. 5.1); срок поставки — 14 рабочих дней с получения заявки (п. 3.1).", src((PT05, "п. 7.1"), (PT05, "п. 5.1"), (PT05, "п. 3.1"))),
    ("Как изменить условия договора аренды склада?", "Изменения и дополнения оформляются дополнительными соглашениями в письменной форме (п. 6.1 договора № А-08/2024).", src((A, "п. 6.1"))),
    ("Как вернуть склад арендодателю при прекращении договора?", "Возвратить помещение по акту в состоянии, в котором оно было получено, с учётом нормального износа (п. 6.3 договора № А-08/2024).", src((A, "п. 6.3"))),
]
MULTI = [
    ("Куда будет приходить мебель от «Альфа-Трейд» и сколько мы платим за это помещение?", "По доп. соглашению № 1 (для спецификаций после 01.10.2024) — склад в г. Химки, ул. Заводская, д. 15, склад № 3. Это помещение арендуется у «Северного Склада» за 450 000 руб. в месяц с НДС (пп. 1.1, 3.1 договора № А-08/2024).", src((DS1, "п. 3.2 в новой ред."), (A, "п. 1.1"), (A, "п. 3.1"))),
    ("Какие сроки в рабочих днях установлены в регламенте, письме комплаенса и служебной записке?", "Регламент (ред. от 01.03.2025): юротдел — 3, главбух — 2, продление до 2 (п. 2.2); оригинал в юротдел — 3 (п. 3.2). Письмо № К-12: санкционная проверка — 3. Служебная записка № ЮО-7: выдача оригинала — не более 3, скан в СЭД — не позднее 1.", src((R25, "п. 2.2"), (R25, "п. 3.2"), (K12, "абз. 4"), (SZ, "абз. 3–4"))),
    ("Сравни гарантию по двум договорам поставки.", "«Альфа-Трейд» (№ П-17/2024): 24 месяца с даты поставки (п. 5.2). «Альфа-Трейдинг» (№ ПТ-05/2023): срок устанавливает производитель, указан в гарантийном талоне (п. 6.1).", src((P17, "п. 5.2"), (PT05, "п. 6.1"))),
    ("Сравни сроки поставки двух поставщиков.", "«Альфа-Трейд»: 10 рабочих дней с даты подписания Спецификации (п. 3.1 № П-17/2024). «Альфа-Трейдинг»: 14 рабочих дней с даты получения заявки (п. 3.1 № ПТ-05/2023).", src((P17, "п. 3.1"), (PT05, "п. 3.1"))),
    ("Сравни порядок разрешения споров по договорам поставки.", "№ П-17/2024: обязательная претензия, ответ 15 календарных дней, затем Арбитражный суд г. Москвы (пп. 8.1–8.2). № ПТ-05/2023: переговоры, при недостижении согласия — Арбитражный суд г. Москвы (п. 7.1).", src((P17, "п. 8.1"), (P17, "п. 8.2"), (PT05, "п. 7.1"))),
    ("Сравни сроки действия всех наших договоров.", "Аренда № А-08/2024 — на неопределённый срок (п. 2.2). Поставка № П-17/2024 — до 31.12.2026 (п. 9.1). Поставка № ПТ-05/2023 — до 31.12.2024 с ежегодной автопролонгацией, если никто не заявит о прекращении за 30 дней (п. 8.1).", src((A, "п. 2.2"), (P17, "п. 9.1"), (PT05, "п. 8.1"))),
    ("Что изменилось в Регламенте согласования в редакции 2025 года по сравнению с 2023?", "Пороги: финдиректор — свыше 3 млн вместо 1 млн (п. 2.3), гендиректор — свыше 15 млн вместо 10 млн (п. 2.4). Согласование в СЭД вместо бумажного листа (пп. 1.4, 3.1). Новое: продление сроков до 2 р. д. (п. 2.2), поручительство/залог (п. 2.5), типовые формы (п. 4.1), аренда, ПДн, аффилированные лица (пп. 5.1–5.3), для иностранных — споры и валютный контроль (п. 5.4).", src((R25, "п. 2.3"), (R25, "п. 2.4"), (R25, "п. 3.1"), (R25, "п. 5.4"), (R23, "п. 2.3"), (R23, "п. 3.1"))),
    ("Как менялись требования к договорам с иностранными контрагентами с 2023 по 2025 год?", "По ред. от 10.01.2023 — доп. согласование с юротделом по применимому праву (п. 4.1). С 01.03.2025 — проверка юротделом, включая применимое право и споры, и валютный контроль (п. 5.4 ред. 2025). С 21.04.2025 — ещё санкционная проверка комплаенсом до подписания (письмо № К-12).", src((R23, "п. 4.1"), (R25, "п. 5.4"), (K12, "абз. 3"))),
    ("Машина «Альфа-Трейд» привезёт мебель на склад в Химках ночью. Её пропустят?", "Склад в Химках — новый адрес доставки по доп. соглашению № 1. По договору аренды № А-08/2024 арендодатель обязан обеспечить круглосуточный доступ арендатора и его транспорта (п. 4.3); о транспорте поставщика договор прямо не говорит, поэтому пропуск машины поставщика ночью нужно согласовать с арендодателем.", src((DS1, "п. 3.2 в новой ред."), (A, "п. 4.3"))),
    ("Отдаём обработку ПДн клиентов подрядчику. Кто согласует договор и чем рискуем без согласия клиентов?", "Договор согласуется с ответственным за организацию обработки ПДн (п. 5.2 Регламента), юротделом и главбухом (п. 2.1). Если в согласии должно быть указано лицо, обрабатывающее ПДн по поручению (п. 6 ч. 4 ст. 9 152-ФЗ), а его нет — это нарушение требований к составу согласия: штраф для юрлиц 300 000–700 000 руб. (ч. 2 ст. 13.11 КоАП РФ).", src((R25, "п. 5.2"), (FZ152, "ч. 4"), (KOAP, "ч. 2"))),
    ("Принимаем сезонного работника на 3 месяца. Какой договор и какое испытание?", "Срочный трудовой договор — основание сезонные работы (ТК РФ, ст. 59). При договоре от 2 до 6 месяцев испытание не может превышать 2 недель (ст. 70).", src((TK59, "ч. 1"), (TK70, "ч. 6"))),
    ("Мы на общем режиме. Какие ставки НДС и налога на прибыль есть в базе?", "НДС: 22% по общему правилу для отгрузок с 01.01.2026 (п. 3 ст. 164 НК РФ), 10% для отдельных продовольственных и иных товаров (п. 2), 0% при экспорте (п. 1). Налог на прибыль — 25% (п. 1 ст. 284 НК РФ).", src((NK164, "пп. 1–3"), (NK284, "п. 1"))),
    ("Договор аренды склада бессрочный. Сколько хранить его оригинал?", "Оригинал хранится 5 лет после окончания срока действия договора или исполнения обязательств (служебная записка № ЮО-7). Договор № А-08/2024 заключён на неопределённый срок (п. 2.2), поэтому срок хранения начнётся только после его прекращения.", src((SZ, "абз. 2"), (A, "п. 2.2"))),
    ("Поставщик — иностранная компания, аффилированная с нами, договор на 2 млн сейчас. Что нужно?", "Финансовый директор — независимо от суммы, так как аффилированное лицо (п. 5.3); юротдел и главбух (п. 2.1); проверка юротделом и валютный контроль (п. 5.4 Регламента в ред. от 01.03.2025); санкционная проверка комплаенсом до подписания (письмо № К-12).", src((R25, "п. 5.3"), (R25, "п. 2.1"), (R25, "п. 5.4"), (K12, "абз. 3"))),
    ("Компания выступает поручителем по договору на 20 млн. Кто согласует?", "Юротдел и главбух (п. 2.1), финансовый директор (поручительство — независимо от суммы, п. 2.5; также свыше 3 млн, п. 2.3) и одобрение генерального директора до подписания — свыше 15 млн (п. 2.4 Регламента в ред. от 01.03.2025).", src((R25, "п. 2.1"), (R25, "п. 2.5"), (R25, "п. 2.4"))),
    ("Что общего и разного в неустойках по всем трём договорам?", "Везде неустойка считается в процентах за каждый день просрочки. Аренда № А-08/2024 — пени 0,1% от задолженности (п. 5.1). Поставка № П-17/2024 — 0,1%, не более 10% (пп. 7.1–7.2) и лимит ответственности 50% цены (п. 7.5). Поставка № ПТ-05/2023 — 0,05% без предела (пп. 5.1–5.2).", src((A, "п. 5.1"), (P17, "п. 7.1"), (P17, "п. 7.5"), (PT05, "п. 5.1"))),
    ("Какие документы базы касаются хранения и передачи оригиналов договоров?", "Регламент в ред. от 01.03.2025: оригинал передаётся в юротдел в течение 3 рабочих дней с подписания (п. 3.2). Служебная записка № ЮО-7: хранение в архиве (каб. 412) 5 лет после окончания действия, выдача по заявке в СЭД не более чем на 3 рабочих дня, скан в СЭД — не позднее 1 рабочего дня.", src((R25, "п. 3.2"), (SZ, "весь документ"))),
    ("Сотрудник отработал 3 часа сверхурочно, ставка 500 руб./час. Законно ли это и сколько заплатить?", "Законно при письменном согласии и в пределах 4 часов в день и 120 часов в год (ТК РФ, ст. 99). Оплата не менее: 2 часа × 750 руб. + 1 час × 1000 руб. = 2500 руб. (ст. 152), либо дополнительный отдых по желанию работника.", src((TK99, "ч. 2, 6"), (TK152, "ч. 1"))),
    ("Утечка данных 3 тысяч клиентов, мы не уведомили Роскомнадзор. Какие штрафы грозят компании?", "За утечку данных 1 000–10 000 субъектов — 3–5 млн руб. (ч. 12 ст. 13.11 КоАП РФ) и за неуведомление уполномоченного органа об утечке — 1–3 млн руб. (ч. 11).", src((KOAP, "ч. 11, 12"))),
    ("У нас НДС-освобождение, но выручка за 3 месяца выросла до 2,5 млн. Что будет и какая ставка дальше?", "Право на освобождение утрачивается с 1-го числа месяца превышения, налог за этот месяц восстанавливается (п. 5 ст. 145 НК РФ). Далее — общие ставки: 22% для отгрузок с 01.01.2026 (п. 3 ст. 164), если не применимы 10% или 0%.", src((NK145, "п. 5"), (NK164, "п. 3"))),
]

